    pipeline: ["ripretinib", "avapritinib", "liquid-biopsy", "velzatinib", "bezuclastinib", "idrx-42", "nb003"],
    openProblems: ["Polyclonal resistance: different lesions carry different secondary KIT mutations.", "SDH-deficient and other wild-type GIST have no effective TKI.", "Optimal duration of adjuvant imatinib (3 vs 5-6 years).", "Long-term imatinib toxicity and adherence."],
    targets: ["kit", "pdgfra", "ntrk", "braf"], technologies: ["kinase-inhibitors", "liquid-biopsy", "robotic-surgery", "endoscopic-resection"],
