    pipeline: ["temsirolimus", "vinorelbine", "car-t", "b7h3", "cobolimab"],
    openProblems: ["Metastatic alveolar RMS: survival <30% for 30 years.", "PAX3-FOXO1 is an undrugged fusion transcription factor.", "Local-control morbidity in young children (orbit, bladder, prostate).", "Relapse after intermediate-risk therapy is rarely curable."],
