    pipeline: ["sodium-thiosulfate", "liver-transplant-oncology"],
    openProblems: ["Metastatic and low-AFP disease.", "Long-term effects of cisplatin (hearing, kidney) and doxorubicin (heart).", "Rising incidence with extreme prematurity.", "Transplant organ availability and lifelong immunosuppression in children."],
    targets: [], technologies: ["platinum", "cytotoxic-chemotherapy", "liver-transplant-oncology", "hcc-surveillance", "ultrasound", "survivorship-care-plan"],
